async function captureToolResult(args: string[]): Promise<void> {
  const separator = args.indexOf("--");
  if (separator < 0) fail("tool-result capture requires -- before the command");
  const options = args.slice(0, separator);
  const argv = args.slice(separator + 1);
  if (options.length !== 2 || options[0] !== "--producer") {
    fail("tool-result capture requires exactly --producer <test|build|git>");
  }
  const producer = options[1];
  if (producer !== "test" && producer !== "build" && producer !== "git") {
    fail("--producer must be one of test, build, git");
  }
  if (argv.length === 0) fail("tool-result capture requires a command after --");
  const sessionId = process.env.CODEX_SESSION_ID;
  if (!sessionId) fail("TOOL_RESULT_SESSION_MISSING: CODEX_SESSION_ID was not supplied by the host");
  const binding = await requireWorkContextBinding({ bindingId: bindingIdForSession("codex", sessionId) });
  const receipt = await captureCommandResult({ argv, producer, binding, cwd: process.cwd() });
  const rendered = `${JSON.stringify(receipt)}\n`;
  if (Buffer.byteLength(rendered) > TOOL_RESULT_MAX_INLINE_BYTES) {
    fail("TOOL_RESULT_RECEIPT_TOO_LARGE: capture receipt exceeded the inline contract");
  }
  process.stdout.write(rendered);
  process.exitCode = receipt.summary.exit_code;
}

function fail(message: string, exitCode = 1): never {
  console.error(message);
  process.exit(exitCode);
  throw new Error(message);
}

function isStringFlagKey(key: string): key is StringFlagKey {
  return stringFlagKeys.includes(key as StringFlagKey);
}

function parseFlags(args: string[]): Flags {
  const flags: Flags = { _: [] };
  for (let index = 0; index < args.length; index += 1) {
    const arg = args[index];
    if (!arg.startsWith("--")) {
      flags._.push(arg);
      continue;
    }
    const key = arg.slice(2);
    if (key === "json" || key === "staleness") {
      flags[key] = true;
      continue;
    }
    if (!isStringFlagKey(key)) fail(`Unknown flag --${key}`);
    const value = args[index + 1];
    if (value === undefined || value.startsWith("--")) fail(`Missing value for --${key}`);
    flags[key] = value;
    index += 1;
  }
  return flags;
}

function requiredFlag(flags: Flags, key: keyof Flags): string {
  const value = flags[key];
  if (typeof value !== "string" || value.trim().length === 0) fail(`Missing required --${String(key)}`);
  return value;
}

function parseSkillInvocationOutcome(value: string | undefined): SkillInvocationOutcome {
  if (value === "used" || value === "missed" || value === "false_positive") return value;
  fail("--outcome must be one of used, missed, false_positive");
}

function parseBrainUsageEvent(value: string | undefined): BrainUsageEvent {
  if (BRAIN_USAGE_EVENTS.includes(value as BrainUsageEvent)) return value as BrainUsageEvent;
  fail(`--event must be one of ${BRAIN_USAGE_EVENTS.join(", ")}`);
}

function parseBrainUsageSeverity(value: string | undefined): BrainUsageSeverity | undefined {
  if (value === undefined) return undefined;
  if (BRAIN_USAGE_SEVERITIES.includes(value as BrainUsageSeverity)) return value as BrainUsageSeverity;
  fail(`--severity must be one of ${BRAIN_USAGE_SEVERITIES.join(", ")}`);
}

